func ptrEDIInboundFile(p unsafe.Pointer, c int32) any {
	r := (*ediinboundfile.EDIInboundFile)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CommunicationProfileID))
	case 4:
		return (*string)(unsafe.Pointer(&r.EDIPartnerID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Method))
	case 6:
		return &r.RemotePath
	case 7:
		return &r.FileName
	case 8:
		return &r.Checksum
	case 9:
		return &r.SizeBytes
	case 10:
		return &r.RawContent
	case 11:
		return &r.InterchangeControlNumber
	case 12:
		return &r.ISASenderQualifier
	case 13:
		return &r.ISASenderID
	case 14:
		return &r.ISAReceiverQualifier
	case 15:
		return &r.ISAReceiverID
	case 16:
		return (*string)(unsafe.Pointer(&r.Status))
	case 17:
		return &r.FailureReason
	case 18:
		return (*int64)(unsafe.Pointer(&r.TransactionCount))
	case 19:
		return &r.ReceivedAt
	case 20:
		return &r.ProcessedAt
	case 21:
		return &r.RawPurgedAt
	case 22:
		return &r.Version
	case 23:
		return &r.CreatedAt
	case 24:
		return &r.UpdatedAt
	}
	return nil
}

func valueEDIInboundFile(p unsafe.Pointer, c int32) any {
	r := (*ediinboundfile.EDIInboundFile)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.CommunicationProfileID)
	case 4:
		if r.EDIPartnerID == "" {
			return nil
		}
		return string(r.EDIPartnerID)
	case 5:
		return string(r.Method)
	case 6:
		return r.RemotePath
	case 7:
		return r.FileName
	case 8:
		return r.Checksum
	case 9:
		return r.SizeBytes
	case 10:
		return r.RawContent
	case 11:
		if r.InterchangeControlNumber == "" {
			return nil
		}
		return r.InterchangeControlNumber
	case 12:
		if r.ISASenderQualifier == "" {
			return nil
		}
		return r.ISASenderQualifier
	case 13:
		if r.ISASenderID == "" {
			return nil
		}
		return r.ISASenderID
	case 14:
		if r.ISAReceiverQualifier == "" {
			return nil
		}
		return r.ISAReceiverQualifier
	case 15:
		if r.ISAReceiverID == "" {
			return nil
		}
		return r.ISAReceiverID
	case 16:
		return string(r.Status)
	case 17:
		if r.FailureReason == "" {
			return nil
		}
		return r.FailureReason
	case 18:
		return int64(r.TransactionCount)
	case 19:
		return r.ReceivedAt
	case 20:
		if r.ProcessedAt == nil {
			return nil
		}
		return *r.ProcessedAt
	case 21:
		if r.RawPurgedAt == nil {
			return nil
		}
		return *r.RawPurgedAt
	case 22:
		return r.Version
	case 23:
		return r.CreatedAt
	case 24:
		return r.UpdatedAt
	}
	return nil
}

func attachEDIInboundFile(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*ediinboundfile.EDIInboundFile)(p)
	switch rel {
	case 0:
		r.Partner = (*edi.EDIPartner)(child)
	case 1:
		r.CommunicationProfile = (*edi.EDICommunicationProfile)(child)
	case 2:
		r.Messages = append(r.Messages, (*edimessage.EDIMessage)(child))
	}
}

